        // General rule: after initialize, the stored base token equals the argument.
        assertTrue(c.baseToken() == baseToken);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(uint56 changeFee, uint8 decimals_, uint16 feeRate, uint256 inputAmount) public {
        vm.assume(feeRate <= 5_000);
        vm.assume(decimals_ >= 4 && decimals_ <= 60 && decimals_ != 18);
        vm.assume(changeFee > 0);
        inputAmount = bound(inputAmount, 0, 1e30);

        FixedDecimalsERC20 base = new FixedDecimalsERC20(decimals_);

        C fresh = new C(address(this), address(this), address(this));
        fresh.initialize(address(base), address(base), 1e18, 1e18, changeFee, feeRate, bytes32(0), false, false);

        // The pool must use the initialized ERC20 base token's decimals for change fees.
        (uint256 fee, ) = fresh.changeFeeQuote(inputAmount);
        assertTrue(fee == uint256(changeFee) * 10 ** (decimals_ - 4) * inputAmount / 1e18);
    }
}

contract FixedDecimalsERC20 {
    uint8 public immutable decimals;
    constructor(uint8 d) { decimals = d; }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(uint8 decimals_, uint128 vBase, uint128 vNft) public {
        vm.assume(decimals_ != 18);
        vBase = uint128(bound(vBase, 1, 1e18));
        vNft = uint128(bound(vNft, 1, 1e18));

        FixedDecimalsToken token = new FixedDecimalsToken(decimals_);

        c.initialize(
            address(token),
            address(this),
            vBase,
            vNft,
            0,
            0,
            bytes32(0),
            false,
            false
        );

        assertTrue(c.price() == (uint256(vBase) * 10 ** (36 - uint256(decimals_))) / uint256(vNft));
    }
}

contract FixedDecimalsToken {
    uint8 public immutable d;

    constructor(uint8 decimals_) { d = decimals_; }

    function decimals() external view returns (uint8) { return d; }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    FuzzedToken token;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
        token = new FuzzedToken();
    }

    // test contract acts as the factory, exposing protocolFeeRate
    function protocolFeeRate() external pure returns (uint16) {
        return 0;
    }

    function testFuzz_property(uint56 changeFee, uint8 decimals) public {
        vm.assume(changeFee > 0);
        vm.assume(decimals >= 4);

        token.setDecimals(decimals);

        c.initialize(
            address(token),
            address(token),
            1e18,
            1e18,
            changeFee,
            0,
            bytes32(0),
            false,
            false
        );

        // Rule: the flash fee must be computed from the initialized base token's decimals.
        assertTrue(c.flashFee(address(token), 0) == uint256(changeFee) * 10 ** (decimals - 4));
    }
}

contract FuzzedToken {
    uint8 public decimals = 18;

    function setDecimals(uint8 d) public {
        decimals = d;
    }
}

